<?php $ch = curl_init("http://127.0.0.1:8000/api/gateway?c=Auth&m=login"); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(["username"=>"admin", "password"=>"password"])); curl_setopt($ch, CURLOPT_HTTPHEADER, ["Content-Type: application/json", "Accept: application/json"]); $resp = curl_exec($ch); echo "Response: " . $resp . "\n"; echo "HTTP Code: " . curl_getinfo($ch, CURLINFO_HTTP_CODE) . "\n";
